import sys
from datetime import date, timedelta


def parse(text):
    y, m, d = map(int, text.split("-"))
    return date(y, m, d)


def main():
    lines = [line.split() for line in sys.stdin if line.strip()]
    ref_date = parse(lines[0][0])
    counts = {"child": 0, "teen": 0, "adult": 0, "senior": 0}
    for name, birth_str in lines[1:]:
        birth_date = parse(birth_str)
        # Compute age as number of completed years at reference date
        age = ref_date.year - birth_date.year
        # Adjust if birthday hasn't occurred yet this year
        if ref_date.month < birth_date.month or (
            ref_date.month == birth_date.month and ref_date.day < birth_date.day
        ):
            age -= 1
        if age <= 12:
            group = "child"
        elif age <= 17:
            group = "teen"
        elif age <= 64:
            group = "adult"
        else:
            group = "senior"
        counts[group] += 1
        print(f"{name} {age} {group}")
    print("child", counts["child"])
    print("teen", counts["teen"])
    print("adult", counts["adult"])
    print("senior", counts["senior"])


if __name__ == "__main__":
    main()
